function conventionPicker(value,scope){const selected=Conventions.find(value),custom=Boolean(String(value??'').trim())&&!selected;const state=selected?selected.idcc:custom?'custom':'';return `<div class="convention-picker wide" data-convention-scope="${scope}"><label>Rechercher une convention collective<input id="${scope}-cc-search" type="search" placeholder="Ex. bâtiment, ÉCLAT, Syntec, 1596…" aria-label="Rechercher une convention — ${scope==='company'?'entreprise':'salarié'}" oninput="filterConventions('${scope}')" onkeydown="if(event.key==='Enter')event.preventDefault()"></label><label>${scope==='company'?'Convention collective de référence de l’entreprise':'Convention collective applicable au salarié'}<select id="${scope}-cc-select" onchange="chooseConvention('${scope}')" aria-label="Choisir une convention — ${scope==='company'?'entreprise':'salarié'}">${conventionOptions('',state,scope)}</select></label><input type="hidden" name="idcc" id="${scope}-cc-value" value="${esc(value??'')}"><label id="${scope}-cc-custom-label" ${custom?'':'hidden'}>Autre convention / valeur déjà saisie<input id="${scope}-cc-custom" type="text" maxlength="300" value="${esc(custom?value:'')}" placeholder="Numéro IDCC et nom de la convention" oninput="customConvention('${scope}')"></label><p id="${scope}-cc-count" class="muted" role="status">${Conventions.catalog.length} conventions proposées · liste non exhaustive</p><p class="muted">${scope==='employee'?'Sans choix spécifique, le bulletin reprend la convention de l’entreprise. ':''}La convention doit être confirmée selon le dossier ; le code APE seul ne suffit pas. Le choix ne charge pas les règles de calcul de paie.</p><a href="https://code.travail.gouv.fr/outils/convention-collective/convention" target="_blank" rel="noopener noreferrer">Vérifier sur le Code du travail numérique ↗</a></div>`;}
function conventionOptions(query,current,scope){const matches=Conventions.search(query),selected=Conventions.catalog.find(c=>c.idcc===current);let options=`<option value="" ${current===''?'selected':''}>${scope==='employee'?'Reprendre la convention de l’entreprise / à définir':'À définir — choisir une convention'}</option><option value="custom" ${current==='custom'?'selected':''}>Autre convention / saisie libre</option>`;if(selected&&!matches.some(c=>c.idcc===current))options+=`<optgroup label="Choix actuel"><option selected value="${selected.idcc}">IDCC ${selected.idcc} — ${esc(selected.name)}</option></optgroup>`;for(const sector of [...new Set(matches.map(c=>c.sector))])options+=`<optgroup label="${esc(sector)}">${matches.filter(c=>c.sector===sector).map(c=>`<option value="${c.idcc}" ${current===c.idcc?'selected':''}>IDCC ${c.idcc} — ${esc(c.name)}</option>`).join('')}</optgroup>`;return options;}
function filterConventions(scope){const input=$('#'+scope+'-cc-search'),select=$('#'+scope+'-cc-select');const value=select.value;select.innerHTML=conventionOptions(input.value,value,scope);const n=Conventions.search(input.value).length;$('#'+scope+'-cc-count').textContent=n?n+' convention(s) correspondant à la recherche.':'Aucune correspondance dans cette sélection. Utilisez « Autre convention / saisie libre ».';}
function chooseConvention(scope){const choice=$('#'+scope+'-cc-select').value,label=$('#'+scope+'-cc-custom-label'),hidden=$('#'+scope+'-cc-value');label.hidden=choice!=='custom';if(choice==='custom'){hidden.value=$('#'+scope+'-cc-custom').value;$('#'+scope+'-cc-custom').focus();}else hidden.value=choice;}
function customConvention(scope){if($('#'+scope+'-cc-select').value==='custom')$('#'+scope+'-cc-value').value=$('#'+scope+'-cc-custom').value;}
